// src/client/WeatherBackdrop.module.css
var css = "/* Animated weather backdrop: an inline SMIL-animated Meteocons SVG behind\n   the card content. Decor only \u2014 never intercepts pointer events. The SVG\n   is 128x128 and scaled up; opacity keeps it a soft background layer on\n   both themes, with a gradient fade so the text stays readable. */\n\n.61617f0a_backdrop {\n  position: absolute;\n  inset: 0;\n  overflow: hidden;\n  border-radius: inherit;\n  pointer-events: none;\n  z-index: 0;\n  opacity: 0.55;\n}\n\n/* The injected SVG fills the backdrop area, anchored to the top-right so\n   the card head stays clear on the left. The svg is a plain element\n   selector (CSS Modules hashes only class names), so no :global() wrapper\n   is needed \u2014 our esbuild pipeline keeps :global() verbatim, which would\n   make this rule dead in the built bundle. */\n.61617f0a_backdrop svg {\n  position: absolute;\n  top: -50px;\n  right: -22px;\n  width: 168px;\n  height: 168px;\n  display: block;\n}\n\n/* Fade the far edge so the icon melts into the card surface. */\n.61617f0a_backdrop::after {\n  content: '';\n  position: absolute;\n  inset: 0;\n  background: linear-gradient(\n    135deg,\n    var(--dsw-alias-bg-layer-2) 0%,\n    transparent 55%\n  );\n  pointer-events: none;\n}\n\n/* Dark theme: the bright Meteocons fill palette pops harder on a near-black\n   card, so pull the whole layer back a bit. */\nbody[data-ds-dark-theme] .61617f0a_backdrop {\n  opacity: 0.4;\n}\n";
var tagId = "dsh-client-ui-weather/src/client/WeatherBackdrop.module.css";
if (typeof document !== "undefined" && document.querySelector('style[data-plugin-css="' + tagId + '"]') === null) {
  const tag = document.createElement("style");
  tag.dataset.plugin = "dsh-client-ui-weather";
  tag.dataset.pluginCss = tagId;
  tag.textContent = css;
  document.head.appendChild(tag);
}
var WeatherBackdrop_default = { "backdrop": "61617f0a_backdrop" };

